<script setup lang="ts">
import QuoteOcrPanel from './QuoteOcrPanel.vue'
import {decimalProduct,type QuoteOcrDraft} from './quote-ocr'
import QuoteLines from '@/shared/ui/QuoteLines.vue'
import {quotePayload} from '@/shared/ui/presentation'
import RecordList from '@/shared/ui/RecordList.vue'
import {label} from '@/shared/ui/presentation'
import {computed,onMounted,ref,watch} from 'vue'
import {currentUser,httpClient} from '@/shared/http/client'
import {formalPayload,quotationApi,type QuoteCase} from './quotation'
const props=defineProps<{caseId:string;refreshToken?:number}>(),emit=defineEmits<{changed:[]}>(),api=quotationApi(httpClient,props.caseId)
const cs=computed(()=>currentUser.value?.roles.includes('CUSTOMER_SERVICE')),staff=computed(()=>cs.value||currentUser.value?.roles.includes('ADMIN')),shop=computed(()=>currentUser.value?.roles.includes('REPAIR_SHOP'))
const data=ref<QuoteCase>(),busy=ref(false),message=ref(''),draftLines=ref<QuoteOcrDraft[]>([{description:'',quantity:'',unitPrice:''}]),mode=ref<'FIXED_AMOUNT'|'PERCENTAGE'>('FIXED_AMOUNT'),markup=ref('0.00'),assessment=ref(''),historyType=ref(shop.value?'RAW':'EVENT'),historyPage=ref(1),historyTotal=ref(0),history=ref('')
const editable=computed(()=>data.value&&['ARRIVED','WAITING_QUOTE','QUOTE_REVIEWING','WAITING_INSURER_ASSESSMENT','WAITING_REPAIR_AUTHORIZATION'].includes(data.value.status))
const ocrPanel=ref<InstanceType<typeof QuoteOcrPanel>>(),quoteCommand=ref<{body:string;key:string}>()
async function load(){data.value=await api.get()}
async function run(action:()=>Promise<void>){busy.value=true;message.value='';try{await action()}catch(e){message.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function post(path:string,body:unknown){data.value=await api.post(path,body);message.value='已保存；历史版本保留';emit('changed')}
async function submit(){if(!data.value)return;quotePayload(draftLines.value);const reviewed=await ocrPanel.value?.prepare(draftLines.value)??draftLines.value;const lines=quotePayload(reviewed).map((line,index)=>({...line,ocr:reviewed[index]?.ocr})),body={expectedVersion:data.value.version,assignmentVersion:data.value.assignmentVersion,lines},encoded=JSON.stringify(body);if(!quoteCommand.value||quoteCommand.value.body!==encoded)quoteCommand.value={body:encoded,key:crypto.randomUUID()};data.value=await api.post('raw-quotes',body,quoteCommand.value.key);draftLines.value=[{description:'',quantity:'',unitPrice:''}];message.value='已提交不可变报价新版本；OCR来源已保留';emit('changed')}
async function approve(){if(!data.value?.rawQuote)throw Error('需先有当前网点原始报价');await post('formal-quotes',formalPayload(data.value.version,data.value.rawQuote.id,mode.value,markup.value))}
async function recordAssessment(){if(!data.value)return;await post('assessments',{expectedVersion:data.value.version,amount:assessment.value})}
async function confirm(kind:'INSURER'|'CUSTOMER_SERVICE'){if(!data.value)return;await post(`confirmations/${kind}`,{expectedVersion:data.value.version})}
async function start(){if(!data.value)return;await post('start-repair',{expectedVersion:data.value.version,assignmentVersion:data.value.assignmentVersion})}
async function loadHistory(){const result=await api.history(historyType.value,historyPage.value);historyTotal.value=result.total;history.value=JSON.stringify(result.records,null,2)}
async function exportCsv(){if(!data.value?.formalQuote)return;const blob=await api.export(data.value.formalQuote.id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`quote-v${data.value.formalQuote.version}.csv`;a.click();URL.revokeObjectURL(url)}
onMounted(()=>run(load));watch(()=>props.refreshToken,()=>run(load))
</script>
<template><section class="quotation"><p class="eyebrow">QUOTE / AUTHORIZATION</p><h2>{{ shop?'原始报价与维修授权':'报价、核损与维修授权' }}</h2><button :disabled="busy" @click="run(load)">刷新当前状态</button><p role="status">{{ message }}</p><template v-if="data"><p>状态 {{ label(data.status) }}；当前版本 {{ data.version }}</p><p v-if="shop">这里只展示本店原始报价与四项授权结果，内部价格信息由服务端隔离。</p><p v-else>币种 CNY，单位元；金额来自后端。正式对外行金额为准，展示单价保留6位。</p>
<div v-if="data.rawQuote"><h3>网点原始报价 v{{ data.rawQuote.version }}</h3><p>原始合计 {{ data.rawQuote.total }} 元</p><QuoteLines :lines="data.rawQuote.lines"/></div><div v-if="shop&&editable"><h3>提交原始报价新版本</h3><p>单价以元填写，最多2位小数；每次提交保留新版本。</p><QuoteOcrPanel v-if="data.assignmentVersion!==undefined" ref="ocrPanel" :key="data.assignmentVersion" :case-id="caseId" :assignment-version="data.assignmentVersion" :lines="draftLines" :locked="busy" @merge="draftLines=$event"/><fieldset v-for="(line,index) in draftLines" :key="index"><legend>报价第{{ index+1 }}项</legend><p v-if="line.ocr">OCR来源 · 候选{{ line.ocr.itemIndex+1 }}，须人工核对；单位 {{ line.unit||'未识别' }}，单据原行金额 {{ line.lineAmount||'未识别' }}；当前程序计算 {{ decimalProduct(line.quantity,line.unitPrice)||'待补充' }} 元。{{ line.lineAmount&&decimalProduct(line.quantity,line.unitPrice)&&decimalProduct(line.quantity,line.unitPrice)!==decimalProduct('1',line.lineAmount)?'与单据原金额不一致，请核对':'请核对后提交' }}</p><label>项目名称<input v-model="line.description" maxlength="255" :disabled="busy"/></label><label>数量<input v-model="line.quantity" inputmode="numeric" :disabled="busy"/></label><label>单价（元）<input v-model="line.unitPrice" inputmode="decimal" :disabled="busy"/></label><button type="button" :disabled="busy||draftLines.length===1" @click="draftLines.splice(index,1)">删除本项</button></fieldset><button type="button" :disabled="busy" @click="draftLines.push({description:'',quantity:'',unitPrice:''})">增加报价项</button><button :disabled="busy" @click="run(submit)">网点提交报价</button></div>
<div v-if="staff"><template v-if="data.formalQuote"><h3>正式报价 v{{ data.formalQuote.version }}（内部审核）</h3><p>原始合计 {{ data.formalQuote.originalTotal }}；加价 {{ data.formalQuote.markupAmount }}；对外总额 {{ data.formalQuote.total }} 元</p><QuoteLines :lines="data.formalQuote.lines" formal/><button :disabled="busy" @click="run(exportCsv)">导出仅对外价格的 CSV 数据</button></template><div v-if="cs&&editable"><h3>客服审核与总额加价</h3><select v-model="mode"><option value="FIXED_AMOUNT">固定金额（元）</option><option value="PERCENTAGE">比例（10.00代表10%）</option></select><input v-model="markup" inputmode="decimal" aria-label="加价值"><button :disabled="busy||!data.rawQuote" @click="run(approve)">审核并生成正式新版本</button><h3>最终核损金额</h3><input v-model="assessment" inputmode="decimal" placeholder="金额字符串，最多2位小数"><button :disabled="busy" @click="run(recordAssessment)">保存核损新版本</button><p>报价、核损金额或核损材料变化会清除两项确认并撤销旧授权。</p><button :disabled="busy||data.gate.insurerConfirmationRecorded" @click="run(()=>confirm('INSURER'))">代录保司确认</button><button :disabled="busy||data.gate.customerServiceConfirmationRecorded" @click="run(()=>confirm('CUSTOMER_SERVICE'))">客服确认当前依据</button></div><p v-if="data.assessment">最终核损 v{{ data.assessment.version }}：{{ data.assessment.amount }} 元</p></div>
<h3>四项开修条件</h3><ul class="gate-list"><li :class="{done:data.gate.lossAssessmentFileUploaded}"><span>核损单已上传</span><strong>{{ data.gate.lossAssessmentFileUploaded?'已满足':'未满足' }}</strong></li><li :class="{done:data.gate.finalAssessmentAmountRecorded}"><span>最终核损金额已录入</span><strong>{{ data.gate.finalAssessmentAmountRecorded?'已满足':'未满足' }}</strong></li><li :class="{done:data.gate.insurerConfirmationRecorded}"><span>保险公司已确认</span><strong>{{ data.gate.insurerConfirmationRecorded?'已满足':'未满足' }}</strong></li><li :class="{done:data.gate.customerServiceConfirmationRecorded}"><span>客服确认</span><strong>{{ data.gate.customerServiceConfirmationRecorded?'已满足':'未满足' }}</strong></li></ul><p>{{ data.authorized?'当前已授权，可以开始维修。':'条件未齐，请等待客服完成确认；系统会阻止未授权开修。' }}</p><button v-if="shop&&editable" :disabled="busy||!data.gate.allowed" @click="run(start)">开始维修（服务端复核）</button>
<details><summary>版本、确认及授权历史</summary><select v-model="historyType"><option value="RAW">原始报价</option><template v-if="staff"><option value="FORMAL">正式报价</option><option value="ASSESSMENT">核损</option><option value="CONFIRMATION">确认</option><option value="EVENT">授权/变更事件</option></template></select><input v-model.number="historyPage" type="number" min="1" aria-label="历史页码"><button :disabled="busy" @click="run(loadHistory)">查询历史</button><span>共 {{ historyTotal }} 条</span><RecordList :value="history"/></details></template></section></template>
<style scoped>.gate-list{padding:0!important;list-style:none}.gate-list li{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 0!important;border-bottom:1px solid var(--color-border)}.gate-list strong{color:var(--color-warning);font-size:12px}.gate-list li.done strong{color:var(--color-success)}textarea{width:100%;box-sizing:border-box}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
